//! The three files written from the configuration tree: the reference page,
//! the reference TOML holding every key, and the default `ferroehr.toml`
//! holding the operator keys. No specification governs their layout: our own
//! design.

use std::fmt::Write as _;

use crate::model::{Key, Section, Shape, bare};

/// The line every generated file opens with, in its own comment syntax.
const GENERATED: &str =
    "@generated by tools/config-reference from the configuration types. DO NOT EDIT.";

/// The longest comment line the TOML files wrap at.
const WIDTH: usize = 79;

/// The longest prose line of the page, the width the book wraps at
/// (`.mdbook-lint.toml`, MD013).
const PAGE_WIDTH: usize = 100;

/// The reference page: every section and every key, with its type, its
/// default and its description.
pub(crate) fn page(sections: &[Section]) -> String {
    let mut out = String::new();
    let _ = writeln!(out, "<!-- {GENERATED} -->");
    out.push_str(
        "<!-- SPDX-FileCopyrightText: Cadasto B.V. -->\n\
         <!-- SPDX-License-Identifier: BUSL-1.1 -->\n\n\
         # Every configuration key\n\n",
    );
    out.push_str(&wrapped(
        "This page lists every key FerroEHR reads from `ferroehr.toml`, generated from the \
         configuration types, so it always matches the server you run. Each section is one \
         TOML table. A key without a default is unset until you set it. Every key can also \
         be set as an environment variable: `FERROEHR`, then the TOML path with `__` between \
         the segments, such as `FERROEHR__DATABASE__MAX_CONNECTIONS`.",
        PAGE_WIDTH,
    ));
    out.push('\n');
    out.push_str(&wrapped(
        "The shipped `ferroehr.toml` holds only the keys an operator usually sets. The guides \
         under [Configuration reference](configuration.md) explain the sections.",
        PAGE_WIDTH,
    ));
    for section in sections {
        let _ = write!(out, "\n## `{}`\n\n", header(section));
        if !section.description.is_empty() {
            out.push_str(&wrapped(&section.description, PAGE_WIDTH));
            out.push('\n');
        }
        if section.optional && section.shape == Shape::Table {
            out.push_str("The table is optional.\n\n");
        }
        if section.keys.is_empty() {
            out.push_str("The table holds only the tables below.\n");
            continue;
        }
        out.push_str("| Key | Type | Default | Description |\n|---|---|---|---|\n");
        for key in &section.keys {
            let default = match (&key.default, key.required) {
                (Some(default), _) => format!("`{}`", cell(default)),
                (None, true) => "required".to_owned(),
                (None, false) => "unset".to_owned(),
            };
            let _ = writeln!(
                out,
                "| `{}` | {} | {} | {} |",
                key.name,
                cell(&key.kind),
                default,
                cell(&key.description)
            );
        }
    }
    out
}

/// The reference TOML: every key, a key with a default as a live line and
/// any other as a `#?` line, so the file parses to the defaults.
pub(crate) fn reference(sections: &[Section]) -> String {
    let mut out = String::new();
    let _ = writeln!(out, "# {GENERATED}");
    out.push_str(
        "# SPDX-FileCopyrightText: Cadasto B.V.\n\
         # SPDX-License-Identifier: BUSL-1.1\n\
         #\n\
         # Every key of ferroehr.toml with its default. A line marked `#?` is a key with no\n\
         # default, or one whose default is a secret, shown with an example value.\n",
    );
    for section in sections {
        let mode = mode(section, sections);
        write_section(&mut out, section, mode, section.keys.iter().collect());
    }
    out
}

/// The default `ferroehr.toml`: the keys of `operator`, each `(table path,
/// key)`, under the tables that hold them, in the order of `operator`.
///
/// # Errors
/// A message naming each operator key the tree does not hold.
pub(crate) fn defaults(sections: &[Section], operator: &[(&str, &str)]) -> Result<String, String> {
    let mut missing = Vec::new();
    let mut chosen: Vec<(&Section, Vec<&Key>)> = Vec::new();
    for (path, name) in operator {
        let Some(section) = sections.iter().find(|s| s.path == *path) else {
            missing.push(format!("[{path}]"));
            continue;
        };
        let Some(key) = section.keys.iter().find(|k| k.name == *name) else {
            missing.push(format!("{path}.{name}"));
            continue;
        };
        match chosen.iter_mut().find(|(s, _)| s.path == *path) {
            Some((_, keys)) => keys.push(key),
            None => chosen.push((section, vec![key])),
        }
    }
    if !missing.is_empty() {
        return Err(format!(
            "the operator keys name what the configuration does not hold: {}",
            missing.join(", ")
        ));
    }
    let mut out = String::new();
    let _ = writeln!(out, "# {GENERATED}");
    out.push_str(
        "# SPDX-FileCopyrightText: Cadasto B.V.\n\
         # SPDX-License-Identifier: BUSL-1.1\n\
         #\n\
         # ferroehr.toml: the keys an operator usually sets, each with its default.\n\
         # Copy this file to ferroehr.toml and edit it. A line marked `#?` is a key with\n\
         # no default, or one whose default is a secret: remove `#? ` to set it. Every\n\
         # other key is listed on the configuration reference page,\n\
         # https://ferroehr.eu/docs/latest/installation/config-keys.html.\n\
         #\n\
         # A duration is a string with its unit (\"500ms\", \"30s\", \"10min\", \"12h\",\n\
         # \"7d\"), a size a string with an IEC binary unit (\"64MiB\"). Each key can\n\
         # also be set as FERROEHR__<TABLE>__<KEY>, such as\n\
         # FERROEHR__DATABASE__MAX_CONNECTIONS; `--set key=value` wins over it.\n",
    );
    for (section, keys) in chosen {
        write_section(&mut out, section, mode(section, sections), keys);
    }
    Ok(out)
}

/// How a section's lines are written.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Mode {
    /// Live lines, which the file sets.
    Live,
    /// `#?` lines: a table the defaults leave out, written as an example.
    Example,
    /// `#` lines: a table under an operator-chosen name, which no example
    /// can name.
    Comment,
}

/// How `section` is written: a table is live only when it and every table
/// above it are tables the defaults hold.
fn mode(section: &Section, sections: &[Section]) -> Mode {
    let mut mode = Mode::Live;
    for holder in sections.iter().filter(|s| {
        s.path == section.path
            || (!s.path.is_empty() && section.path.starts_with(&format!("{}.", s.path)))
    }) {
        let own = match holder.shape {
            Shape::Named => Mode::Comment,
            Shape::Array => Mode::Example,
            Shape::Table if holder.optional => Mode::Example,
            Shape::Table => Mode::Live,
        };
        mode = match (mode, own) {
            (Mode::Comment, _) | (_, Mode::Comment) => Mode::Comment,
            (Mode::Example, _) | (_, Mode::Example) => Mode::Example,
            (Mode::Live, Mode::Live) => Mode::Live,
        };
    }
    mode
}

/// Writes `section` with `keys` to `out` in `mode`.
fn write_section(out: &mut String, section: &Section, mode: Mode, keys: Vec<&Key>) {
    out.push('\n');
    if !section.description.is_empty() {
        comment(out, &section.description);
    }
    let lead = match mode {
        Mode::Live => "",
        Mode::Example => "#? ",
        Mode::Comment => "# ",
    };
    if !section.path.is_empty() {
        let _ = writeln!(out, "{lead}{}", header(section));
    }
    for key in keys {
        comment(out, &key.description);
        let name = bare(&key.name);
        let (lead, value) = match (&key.default, mode) {
            (Some(default), Mode::Live) if !key.masked => ("", default),
            (Some(default), Mode::Live | Mode::Example) => ("#? ", default),
            (None, Mode::Live | Mode::Example) => ("#? ", &key.example),
            (Some(default), Mode::Comment) => ("# ", default),
            (None, Mode::Comment) => ("# ", &key.example),
        };
        let _ = writeln!(out, "{lead}{name} = {value}");
    }
}

/// The TOML header of `section`.
fn header(section: &Section) -> String {
    match section.shape {
        Shape::Array => format!("[[{}]]", section.path),
        Shape::Table | Shape::Named => format!("[{}]", section.path),
    }
}

/// Writes `text` to `out` as `#` comment lines wrapped at [`WIDTH`].
fn comment(out: &mut String, text: &str) {
    let mut line = String::from("#");
    for word in text.split_whitespace() {
        if line.len() + 1 + word.len() > WIDTH && line.len() > 1 {
            let _ = writeln!(out, "{line}");
            line = String::from("#");
        }
        line.push(' ');
        line.push_str(word);
    }
    if line.len() > 1 {
        let _ = writeln!(out, "{line}");
    }
}

/// `text` as lines of at most `width` characters, each ended by a newline;
/// a word longer than `width` stands on its own line.
fn wrapped(text: &str, width: usize) -> String {
    let mut out = String::new();
    let mut line = String::new();
    for word in text.split_whitespace() {
        if !line.is_empty() && line.chars().count() + 1 + word.chars().count() > width {
            out.push_str(&line);
            out.push('\n');
            line.clear();
        }
        if !line.is_empty() {
            line.push(' ');
        }
        line.push_str(word);
    }
    if !line.is_empty() {
        out.push_str(&line);
        out.push('\n');
    }
    out
}

/// `text` safe inside a Markdown table cell.
fn cell(text: &str) -> String {
    text.replace('|', "\\|")
}
